    elif op in ("reduce", "foreach"):
        states=list(_node(a[0], value, env)); current=list(_node(a[2], value, env))
        for item in states:
            bound=dict(env); _bind_pattern(a[1], item, bound)
            current=list(_node(a[3], current[0] if current else None, bound))
            if op=="foreach" and a[4] is not None:
